mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join Sec_Inquiry_Record sir on sir.Sec_Id = sec.Sec_Id where sir.id = #{id}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Start_Time as secStartTime, sec.Sec_Bidding_Cycle as secBiddingCycle, sec.Sec_Place as secPlace, c1.C_Name as tendereeName, c1.C_Abbreviation as tendereeAbbName, c2.C_Name as sirIntendedUnitName, c2.C_Abbreviation as sirIntendedUnitAbbName, mn.* from Sec_Inquiry_Record mn left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on c1.C_ID=sec.Sec_Tenderee left join SYS_Company c2 on c2.C_ID=mn.Sir_Intended_Unit where mn.Sec_Id IN
#{id}
and mn.State = 7 order by mn.State_Time desc

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Start_Time as secStartTime, sec.Sec_Bidding_Cycle as secBiddingCycle, sec.Sec_Place as secPlace, c1.C_Name as tendereeName, c1.C_Abbreviation as tendereeAbbName, c2.C_Name as sirIntendedUnitName, c2.C_Abbreviation as sirIntendedUnitAbbName, case when pre.P_Name is null then sp.P_Name else pre.P_Name end as pName, case when pre.P_Category is null then sp.p_Category else pre.P_Category end as pCategory, case when pre.P_Build_Model is null then sp.P_Build_Model else pre.P_Build_Model end as pBuildModel, case when dpre.D_Name is null then sp.D_Name else dpre.D_Name end as pCompetentDepartmentName, mn.*, case when mn.P_Id is null then sp.P_Id else mn.P_Id end as pId from Sec_Inquiry_Record mn left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join SYS_Company c1 on c1.C_ID=sec.Sec_Tenderee left join SYS_Company c2 on c2.C_ID=mn.Sir_Intended_Unit left join pre_project pre on pre.P_Id=mn.P_Id left join SYS_Department dpre on dpre.D_Id = pre.p_Competent_Department left join Sec_Bidding_Plan sbp on sbp.Bp_Id=sec.Bp_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = mn.Sec_Id ${authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time DESC

select sec.Sec_Name as secName,
sec.Sec_Type as secType,
sec.Sec_Organize_Form as secOrganizeForm,
sec.Sec_Bidding_Type as secBiddingType,
sec.Sec_Start_Time as secStartTime,
sec.Sec_Bidding_Cycle as secBiddingCycle,
sec.Sec_Place as secPlace,
c1.C_Name as tendereeName,
c1.C_Abbreviation as tendereeAbbName,
c2.C_Name as sirIntendedUnitName,
c2.C_Abbreviation as sirIntendedUnitAbbName,
mn.*
from Sec_Inquiry_Record mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id
left join SYS_Company c1 on c1.C_ID=sec.Sec_Tenderee
left join SYS_Company c2 on c2.C_ID=mn.Sir_Intended_Unit

    
        and mn.Te_Id = #{params.teId}
    
    
            and mn.Sec_Id = #{params.secId}
    
    
        and sec.Sec_Type=#{params.secType}
    
    
        and sec.Sec_Organize_Form=#{params.secOrganizeForm}
    
    
        and sec.Sec_Bidding_Type=#{params.secBiddingType}
    
    
        and mn.State=#{params.state}
    
    
        and INSTR(mn.Sir_Prerequisites,#{params.sirPrerequisites})
    
    
        and INSTR(mn.Sir_Remark,#{params.sirRemark})
    
    
        and INSTR(mn.Create_Uname,#{params.createUname})
    
    
        and INSTR(sec.Sec_Name,#{params.secName})
    
    
        and mn.Sec_Id in (
        Select sp.Sec_Id from Sec_Project sp
        left join Pre_Project sppj on sppj.P_ID = sp.P_Id
        where sppj.P_ID = #{params.projectId}
        )
    
    
        
            
                and likeCname(#{params.tendereeName},c1.C_Id)=true
            
            
                and INSTR(c1.C_Name,#{params.tendereeName})
            
        
    
    
        
            
                and likeCname(#{params.sirIntendedUnitName},c2.C_Id)=true
            
            
                and INSTR(c2.C_Name,#{params.sirIntendedUnitName})
            
        
    
    
        and INSTR(sec.Sec_Place,#{params.secPlace})
    
    
        and INSTR(sec.Sec_Trading_Place,#{params.secTradingPlace})
    
    
        and mn.Sir_Con_Money>=#{params.sirConMoneyStart}
    
    
        and mn.Sir_Con_Money<=#{params.sirConMoneyEnd}
    
    
        and sec.Sec_Start_Time>=#{params.secStartTimeStart}
    
    
        and sec.Sec_Start_Time<=#{params.secStartTimeEnd}
    
    
        and sec.Sec_Bidding_Cycle>=#{params.secBiddingCycleStart}
    
    
        and sec.Sec_Bidding_Cycle<=#{params.secBiddingCycleEnd}
    
    
        and sec.Create_Time>=#{params.createTimeStart}
    
    
        and sec.Create_Time<=#{params.createTimeEnd}
    
    
        and mn.Sec_Id in (
        Select sp.Sec_Id from Sec_Project sp
        left join Pre_Project sppj on sppj.P_ID = sp.P_Id
        left join SYS_Department dep on sppj.P_Competent_Department = dep.D_Id
        
            
                and sp.P_Id=#{params.pId}
            
            
                and INSTR(dep.D_Name,#{params.pCompetentDepartmentName})
            
            
                
                    
                        and likePname(#{params.pName},sppj.P_Id)=true
                    
                    
                        and INSTR(sppj.P_Name,#{params.pName})
                    
                
            
        
        )
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
